    for i in range(3):
        seq = rolls[i:i+4]
        if all(seq[j+1]-seq[j]==1 for j in range(3)):
            return True
        if all(seq[j+1]-seq[j]==-1 for j in range(3)):
            return True
    return False


def score_turn(rolls):
