    for cat1 in CATEGORIES:
        s1 = turn1_scores.get(cat1)
        if s1 is None:
            continue
        for cat2 in CATEGORIES:
            if cat2 == cat1:
                continue
            s2 = turn2_scores.get(cat2)
            if s2 is None:
                continue
            total = s1 + s2
            if best is None or total > best:
                best = total
    return best if best is not None else 0

# compute game scores, handling missing turn

game_scores = {}
for game in range(1, 3000+1):
    turns = by_game.get(game, [])
    if len(turns) == 2:
        t1, t2 = turns
        s = best_game_score(turn_scores[t1], turn_scores[t2])
    elif len(turns) == 1:
        t1 = turns[0]
        s = best_game_score(turn_scores[t1], zero_turn_scores)
    else:
        s = 0
    game_scores[game] = s

player1_wins = 0
player2_wins = 0
for game in range(1, 3000+1, 2):
    s1 = game_scores[game]
    s2 = game_scores[game+1]
    if s1 > s2:
        player1_wins += 1
    elif s2 > s1:
        player2_wins += 1

print('player1_wins', player1_wins, 'player2_wins', player2_wins, 'diff', player1_wins - player2_wins)
